// lookup demo — Espresso (jahdb demo program)
var DATA={"Espresso":"Espresso is pressure-extracted intensity: 18g in, 36g out, 25-30 seconds. The base of milk drinks."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("1:2 coffee to water"));

